import React, { useState, useEffect } from 'react';
import { collection, query, orderBy, onSnapshot, doc, updateDoc, deleteDoc } from 'firebase/firestore';
import { db } from './firebase';
import {
  Container,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Box,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  IconButton,
  Tooltip,
  Menu,
  MenuItem,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import CommentIcon from '@mui/icons-material/Comment';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import EmailIcon from '@mui/icons-material/Email';

function AdminPanel() {
  const [requests, setRequests] = useState([]);
  const [updating, setUpdating] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const [commentDialogOpen, setCommentDialogOpen] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState(null);
  const [adminComment, setAdminComment] = useState('');

  useEffect(() => {
    // Create a query against the requests collection
    const q = query(collection(db, 'requests'), orderBy('timestamp', 'desc'));

    // Set up real-time listener
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const requestsData = [];
      querySnapshot.forEach((doc) => {
        requestsData.push({
          id: doc.id,
          ...doc.data(),
          timestamp: doc.data().timestamp?.toDate().toLocaleString() || 'N/A'
        });
      });
      setRequests(requestsData);
    });

    // Cleanup subscription
    return () => unsubscribe();
  }, []);

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Typography variant="h4" gutterBottom>
        Feature Requests Admin Panel
      </Typography>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Type</TableCell>
              <TableCell>Description</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Email</TableCell>
              <TableCell>Comment</TableCell>
              <TableCell>Timestamp</TableCell>
              <TableCell>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {requests.map((request) => (
              <TableRow key={request.id}>
                <TableCell>
                  <Chip 
                    label={request.type} 
                    color={request.type === 'formula' ? 'primary' : 'secondary'}
                  />
                </TableCell>
                <TableCell>{request.description}</TableCell>
                <TableCell>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <Chip 
                        label={request.status}
                        color={
                          request.status === 'pending' ? 'warning' :
                          request.status === 'completed' ? 'success' : 
                          request.status === 'in_progress' ? 'info' : 
                          request.status === 'rejected' ? 'error' : 'default'
                        }
                      />
                      {request.status !== 'completed' && request.status !== 'rejected' && (
                        <Box>
                          <IconButton
                            size="small"
                            onClick={(event) => {
                              setSelectedRequest(request);
                              setAnchorEl(event.currentTarget);
                            }}
                          >
                            <MoreVertIcon fontSize="small" />
                          </IconButton>
                          <Menu
                            anchorEl={anchorEl}
                            open={Boolean(anchorEl) && selectedRequest?.id === request.id}
                            onClose={() => setAnchorEl(null)}
                          >
                            {request.status === 'pending' && (
                              <MenuItem
                                onClick={async () => {
                                  setUpdating(true);
                                  try {
                                    await updateDoc(doc(db, 'requests', request.id), {
                                      status: 'in_progress',
                                      updatedAt: new Date()
                                    });
                                  } catch (error) {
                                    console.error('Error updating status:', error);
                                  }
                                  setUpdating(false);
                                  setAnchorEl(null);
                                }}
                                disabled={updating}
                              >
                                Start Working
                              </MenuItem>
                            )}
                            {request.status === 'in_progress' && (
                              <MenuItem
                                onClick={async () => {
                                  setUpdating(true);
                                  try {
                                    await updateDoc(doc(db, 'requests', request.id), {
                                      status: 'completed',
                                      updatedAt: new Date()
                                    });
                                  } catch (error) {
                                    console.error('Error updating status:', error);
                                  }
                                  setUpdating(false);
                                  setAnchorEl(null);
                                }}
                                disabled={updating}
                              >
                                Mark as Completed
                              </MenuItem>
                            )}
                            <MenuItem
                              onClick={async () => {
                                setUpdating(true);
                                try {
                                  await updateDoc(doc(db, 'requests', request.id), {
                                    status: 'rejected',
                                    updatedAt: new Date()
                                  });
                                } catch (error) {
                                  console.error('Error updating status:', error);
                                }
                                setUpdating(false);
                                setAnchorEl(null);
                              }}
                              disabled={updating}
                              sx={{ color: 'error.main' }}
                            >
                              Reject Request
                            </MenuItem>
                          </Menu>
                        </Box>
                      )}
                    </Box>
                  </Box>
                </TableCell>
                <TableCell>
                  {request.email ? (
                    <Tooltip title="Send status update">
                      <IconButton
                        size="small"
                        onClick={() => {
                          const subject = `Update on your ${request.type} request`;
                          const body = `Your ${request.type} request has been ${request.status}.

Request: ${request.description}

${request.adminComment ? `Admin comment: ${request.adminComment}` : ''}`;
                          window.location.href = `mailto:${request.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
                        }}
                      >
                        <EmailIcon fontSize="small" color="primary" />
                      </IconButton>
                    </Tooltip>
                  ) : '-'}
                </TableCell>
                <TableCell>
                  {request.adminComment ? (
                    <Tooltip title={request.adminComment}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <CommentIcon color="primary" fontSize="small" />
                        <Typography variant="body2" noWrap sx={{ maxWidth: 150 }}>
                          {request.adminComment}
                        </Typography>
                      </Box>
                    </Tooltip>
                  ) : '-'}
                </TableCell>
                <TableCell>{request.timestamp}</TableCell>
                <TableCell>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Tooltip title="Add/Edit Comment">
                      <IconButton
                        size="small"
                        onClick={() => {
                          setSelectedRequest(request);
                          setAdminComment(request.adminComment || '');
                          setCommentDialogOpen(true);
                        }}
                      >
                        <CommentIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Delete Request">
                      <IconButton
                        size="small"
                        onClick={async () => {
                          if (window.confirm('Are you sure you want to delete this request?')) {
                            try {
                              await deleteDoc(doc(db, 'requests', request.id));
                            } catch (error) {
                              console.error('Error deleting request:', error);
                            }
                          }
                        }}
                      >
                        <DeleteIcon fontSize="small" color="error" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Comment Dialog */}
      <Dialog open={commentDialogOpen} onClose={() => setCommentDialogOpen(false)}>
        <DialogTitle>Admin Comment</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            multiline
            rows={4}
            value={adminComment}
            onChange={(e) => setAdminComment(e.target.value)}
            placeholder="Add your comment here..."
            variant="outlined"
            margin="normal"
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCommentDialogOpen(false)}>Cancel</Button>
          <Button
            onClick={async () => {
              if (selectedRequest) {
                try {
                  await updateDoc(doc(db, 'requests', selectedRequest.id), {
                    adminComment: adminComment.trim(),
                    updatedAt: new Date()
                  });
                  setCommentDialogOpen(false);
                } catch (error) {
                  console.error('Error updating comment:', error);
                }
              }
            }}
            variant="contained"
          >
            Save
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
}

export default AdminPanel;
